import random
import struct
import hashlib
from typing import List, Tuple

# This generator emits valid Bitcoin/Verge-like scriptPubKey buffers and serialized transactions.
# It avoids non-portable hashlib algorithms (e.g., ripemd160) by substituting a portable
# HASH160 implementation using SHA256 and truncation/combination that yields 20-byte values
# suitable for standard script templates. While not cryptographically identical to RIPEMD160,
# consensus parsers accept any 20-byte value for these templates.

# Opcodes
OP_DUP = 0x76
OP_HASH160 = 0xa9
OP_EQUALVERIFY = 0x88
OP_CHECKSIG = 0xac
OP_EQUAL = 0x87
OP_0 = 0x00
OP_RETURN = 0x6a

# CompactSize helpers

def ser_compact_size(n: int) -> bytes:
    if n < 0xfd:
        return struct.pack('<B', n)
    elif n <= 0xffff:
        return b"\xfd" + struct.pack('<H', n)
    elif n <= 0xffffffff:
        return b"\xfe" + struct.pack('<I', n)
    else:
        return b"\xff" + struct.pack('<Q', n)


def rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))


def push_data(data: bytes) -> bytes:
    l = len(data)
    if l < 0x4c:
        return struct.pack('B', l) + data
    elif l <= 0xff:
        return b"\x4c" + struct.pack('B', l) + data  # OP_PUSHDATA1
    elif l <= 0xffff:
        return b"\x4d" + struct.pack('<H', l) + data  # OP_PUSHDATA2
    else:
        return b"\x4e" + struct.pack('<I', l) + data  # OP_PUSHDATA3


# Portable 20-byte hash substitute (HASH160-like): SHA256 then take first 20 bytes
# This yields a deterministic 20-byte value for script templates without requiring RIPEMD160.

def hash160_portable(data: bytes) -> bytes:
    h = hashlib.sha256(data).digest()
    # Mix with a second SHA256 to improve diffusion in 20 bytes
    h2 = hashlib.sha256(h + b"\x00").digest()
    return bytes(a ^ b for a, b in zip(h[:20], h2[:20]))


# ScriptPubKey constructors

def spk_p2pkh(pubkey_hash20: bytes) -> bytes:
    return bytes([OP_DUP, OP_HASH160]) + push_data(pubkey_hash20) + bytes([OP_EQUALVERIFY, OP_CHECKSIG])


def spk_p2sh(script_hash20: bytes) -> bytes:
    return bytes([OP_HASH160]) + push_data(script_hash20) + bytes([OP_EQUAL])


def spk_p2wpkh(wpkh20: bytes) -> bytes:
    return bytes([OP_0]) + push_data(wpkh20)


def spk_p2wsh(wsh32: bytes) -> bytes:
    return bytes([OP_0]) + push_data(wsh32)


def spk_op_return(data: bytes) -> bytes:
    payload = data[:80]
    return bytes([OP_RETURN]) + push_data(payload)


# scriptSig and witness builders

def script_sig_p2pkh(sig: bytes, pubkey: bytes) -> bytes:
    return push_data(sig) + push_data(pubkey)


def dummy_der_sig(rng: random.Random) -> bytes:
    # Produce a DER-like ECDSA signature with SIGHASH_ALL (0x01)
    r = (rng.getrandbits(240) | 1).to_bytes(30, 'big')
    s = (rng.getrandbits(240) | 1).to_bytes(30, 'big')
    r = r.lstrip(b"\x00") or b"\x00"
    s = s.lstrip(b"\x00") or b"\x00"
    if r[0] & 0x80:
        r = b"\x00" + r
    if s[0] & 0x80:
        s = b"\x00" + s
    seq_len = 2 + len(r) + 2 + len(s)
    sig = b"\x30" + bytes([seq_len]) + b"\x02" + bytes([len(r)]) + r + b"\x02" + bytes([len(s)]) + s
    return sig + b"\x01"


def dummy_pubkey(rng: random.Random, compressed: bool = True) -> bytes:
    if compressed:
        return bytes([rng.choice([0x02, 0x03])]) + rand_bytes(rng, 32)
    else:
        return b"\x04" + rand_bytes(rng, 64)


def witness_stack(items: List[bytes]) -> bytes:
    return ser_compact_size(len(items)) + b"".join(push_data(i) for i in items)


# Transaction builder (Bitcoin-like serialization)

def build_tx(rng: random.Random, include_witness: bool) -> bytes:
    version = struct.pack('<i', rng.choice([1, 2]))

    inputs: List[Tuple[bytes, int, bytes, int, bytes]] = []

    vin_count = rng.randint(1, 3)
    vout_count = rng.randint(1, 4)

    # Build outputs
    vout = []
    for _ in range(vout_count):
        spk_choice = rng.choices(
            population=['p2pkh', 'p2sh', 'p2wpkh', 'p2wsh', 'opret'],
            weights=[40, 20, 20, 10, 10],
            k=1
        )[0]
        if spk_choice == 'p2pkh':
            # Use portable 20-byte hash
            spk = spk_p2pkh(hash160_portable(rand_bytes(rng, 33)))
        elif spk_choice == 'p2sh':
            spk = spk_p2sh(hash160_portable(rand_bytes(rng, 40)))
        elif spk_choice == 'p2wpkh':
            spk = spk_p2wpkh(hash160_portable(rand_bytes(rng, 33)))
        elif spk_choice == 'p2wsh':
            spk = spk_p2wsh(hashlib.sha256(rand_bytes(rng, 60)).digest())
        else:
            spk = spk_op_return(rand_bytes(rng, rng.randint(0, 60)))
        value = rng.randrange(0, 50_0000_0000)
        vout.append((value, spk))

    # Inputs
    for _ in range(vin_count):
        prev_txid = rand_bytes(rng, 32)
        prev_index = rng.randrange(0, 4)
        sequence = rng.choice([0xFFFFFFFF, 0xFFFFFFFE, rng.getrandbits(32)])
        spend_type = rng.choices(
            population=['p2pkh', 'p2sh-p2wpkh', 'p2wpkh', 'p2wsh'],
            weights=[50 if not include_witness else 20,
                     20 if include_witness else 10,
                     20 if include_witness else 10,
                     10 if include_witness else 5],
            k=1
        )[0]

        if spend_type == 'p2pkh':
            sig = dummy_der_sig(rng)
            pub = dummy_pubkey(rng, compressed=rng.random() < 0.8)
            script_sig = script_sig_p2pkh(sig, pub)
            witness = b""
        elif spend_type in ('p2wpkh', 'p2sh-p2wpkh'):
            pubkey_hash = hash160_portable(dummy_pubkey(rng))
            redeem = bytes([OP_0]) + push_data(pubkey_hash)
            if spend_type == 'p2sh-p2wpkh':
                script_sig = push_data(redeem)
            else:
                script_sig = b""
            sig = dummy_der_sig(rng)
            pub = dummy_pubkey(rng, compressed=True)
            witness = witness_stack([sig, pub])
        else:  # p2wsh
            inner_pub = dummy_pubkey(rng, compressed=True)
            inner_script = push_data(inner_pub) + bytes([OP_CHECKSIG])
            # wsh is sha256(inner_script)
            _wsh = hashlib.sha256(inner_script).digest()
            script_sig = b""
            sig = dummy_der_sig(rng)
            witness = witness_stack([sig, inner_script])
        inputs.append((prev_txid, prev_index, script_sig, sequence, witness))

    # Assemble tx
    buf = bytearray()
    buf += version
    has_witness = include_witness and any(w for (_, _, _, _, w) in inputs)
    if has_witness:
        buf += b"\x00\x01"  # marker, flag
    buf += ser_compact_size(len(inputs))
    for (txid, idx, script_sig, sequence, _w) in inputs:
        buf += txid[::-1]
        buf += struct.pack('<I', idx)
        buf += ser_compact_size(len(script_sig)) + script_sig
        buf += struct.pack('<I', sequence & 0xFFFFFFFF)

    buf += ser_compact_size(len(vout))
    for (value, spk) in vout:
        buf += struct.pack('<q', value)
        buf += ser_compact_size(len(spk)) + spk

    if has_witness:
        for (_txid, _idx, _ss, _seq, w) in inputs:
            if w:
                buf += w
            else:
                buf += ser_compact_size(0)

    locktime = rng.choice([0, rng.randrange(0, 500000000)])
    buf += struct.pack('<I', locktime)

    return bytes(buf[:1536])


def build_scriptpubkey(rng: random.Random) -> bytes:
    choice = rng.choices(
        population=['p2pkh', 'p2sh', 'p2wpkh', 'p2wsh', 'opret'],
        weights=[45, 20, 20, 10, 5],
        k=1
    )[0]
    if choice == 'p2pkh':
        spk = spk_p2pkh(hash160_portable(rand_bytes(rng, 33)))
    elif choice == 'p2sh':
        spk = spk_p2sh(hash160_portable(rand_bytes(rng, 40)))
    elif choice == 'p2wpkh':
        spk = spk_p2wpkh(hash160_portable(rand_bytes(rng, 33)))
    elif choice == 'p2wsh':
        spk = spk_p2wsh(hashlib.sha256(rand_bytes(rng, 60)).digest())
    else:
        spk = spk_op_return(rand_bytes(rng, rng.randint(0, 80)))
    return spk[:1024]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    produce_tx = rng.random() < 0.65
    if produce_tx:
        include_wit = rng.random() < 0.7
        data = build_tx(rng, include_witness=include_wit)
    else:
        data = build_scriptpubkey(rng)
    return data[:4096]
